# Marker for metamethod calls that need interpreter help
class LuaMetaCall:
    def __init__(self, func, *args):
        self.func = func
        self.args = args

# Function types
class LuaFunction:
    def __init__(self, proto, closure_env=None):
        self.proto = proto  # could be AST or python callable
        self.closure_env = closure_env or {}

class LuaClosure:
    def __init__(self, func, upvalues):
        self.func = func
        self.upvalues = upvalues

class LuaBuiltin:
    def __init__(self, pyfunc, name="<builtin>"):
        self.pyfunc = pyfunc
        self.name = name
    def __call__(self, *args, **kwargs):
        return self.pyfunc(*args, **kwargs)
    def __repr__(self):
        return f"function: {self.name}"

# Lexer
# Lua tokens
TOKEN_SPEC = [
    ('COMMENT_LONG', r'--\[\[.*?\]\]'),  # not correct multiline, but we handle
    ('COMMENT', r'--.*'),
    ('STRING_LONG', r'\[(=*)\[.*?\]\1\]'),  # long string, will handle specially
    ('STRING', r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\''),
    ('NUMBER_HEX', r'0[xX][0-9a-fA-F]+'),
    ('NUMBER', r'(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?'),
    ('NAME', r'[A-Za-z_][A-Za-z0-9_]*'),
    ('OP', r'\.\.\.|==|~=|<=|>=|\.\.|<<|>>|//|[+\-*/%^#<>=(){}[\];:,.\.]'),
    ('SKIP', r'[ \t\r\n\f]+'),
    ('MISMATCH', r'.'),
]

# For simplicity, we will implement a hand-written lexer scanning character by character.

# Keywords
KEYWORDS = {
    'and', 'break', 'do', 'else', 'elseif', 'end', 'false', 'for', 'function', 'if', 'in', 'local', 'nil', 'not', 'or', 'repeat', 'return', 'then', 'true', 'until', 'while'
}

# For now, implement basic lexer class
class Lexer:
    def __init__(self, text, filename="<string>"):
        self.text = text
        self.pos = 0
        self.len = len(text)
        self.filename = filename
        self.line = 1
        self.col = 1

    def peek(self, n=0):
        p = self.pos + n
        if p >= self.len:
            return ''
        return self.text[p]

    def advance(self, n=1):
        for _ in range(n):
            if self.pos >= self.len:
                return
            c = self.text[self.pos]
            self.pos += 1
            if c == '\n':
                self.line += 1
                self.col = 1
            else:
                self.col += 1

    def skip_whitespace_and_comments(self):
        while True:
            if self.pos >= self.len:
                return
            c = self.peek()
            # whitespace
            if c in ' \t\r\n\f\v':
                self.advance()
                continue
            # comment --
            if c == '-' and self.peek(1) == '-':
                # long comment?
                self.advance(2)
                if self.peek() == '[':
                    # count =
                    j = self.pos
                    eq = 0
                    while j < self.len and self.text[j] == '=':
                        eq+=1
                        j+=1
                    if j < self.len and self.text[j] == '[':
                        # long comment
                        self.pos = j+1
                        # search for ]=eq ]
                        closing = ']' + '='*eq + ']'
                        idx = self.text.find(closing, self.pos)
                        if idx == -1:
                            # unterminated, consume rest
                            self.pos = self.len
                            return
                        else:
                            self.pos = idx + len(closing)
                            # update line count roughly
                            # we need to count newlines inside comment
                            # for simplicity, recalc line from start? Might be expensive, but we can count
                            # We'll count newlines in consumed segment
                            # Already advanced, but line tracking: let's count newlines in segment
                            # To keep simple, just increment line by counting \n in segment
                            # This is approximate
                            # Actually we lost original start pos, but we can count in the comment text we skipped via find
                            # For now, not precise
                            # We'll set line by counting total \n up to pos
                            self.line = self.text[:self.pos].count('\n')+1
                            continue
                # short comment: skip to end of line
                while self.pos < self.len and self.peek() not in '\n\r':
                    self.advance()
                continue
            break

    def read_long_string(self, sep):
        # sep is number of = signs, opening "[=*[": already consumed first [ and =* and second [
        # We are positioned after the second [.
        # We need to find closing ]=*]
        closing = ']' + '='*sep + ']'
        start = self.pos
        idx = self.text.find(closing, start)
        if idx == -1:
            # unterminated
            content = self.text[start:]
            self.pos = self.len
            return content
        content = self.text[start:idx]
        self.pos = idx + len(closing)
        # handle leading newline?
        # Lua: if long string starts with newline, that newline is ignored.
        if content.startswith('\n') or content.startswith('\r'):
            # remove first newline sequence
            if content.startswith('\r\n'):
                content = content[2:]
            elif content.startswith('\n') or content.startswith('\r'):
                content = content[1:]
        return content

    def next_token(self):
        self.skip_whitespace_and_comments()
        if self.pos >= self.len:
            return ('EOF', '', self.line)

        c = self.peek()
        start_line = self.line

        # long string [[ or [=[ etc.
        if c == '[':
            # look ahead for =*[
            j = self.pos+1
            eq = 0
            while j < self.len and self.text[j] == '=':
                eq+=1
                j+=1
            if j < self.len and self.text[j] == '[':
                # long string
                self.pos = j+1
                content = self.read_long_string(eq)
                return ('STRING', content, start_line)
            # else single '['
            self.advance()
            return ('[', '[', start_line)
        if c == ']':
            self.advance()
            return (']', ']', start_line)

        # string literal
        if c == '"' or c == "'":
            quote = c
            self.advance()
            buf = []
            while self.pos < self.len:
                ch = self.peek()
                if ch == quote:
                    self.advance()
                    break
                if ch == '\\':
                    self.advance()
                    if self.pos >= self.len:
                        break
                    esc = self.peek()
                    # Lua escapes: \a \b \f \n \r \t \v \\ \" \' \newline \ddd?
                    if esc == 'a':
                        buf.append('\a'); self.advance()
                    elif esc == 'b':
                        buf.append('\b'); self.advance()
                    elif esc == 'f':
                        buf.append('\f'); self.advance()
                    elif esc == 'n':
                        buf.append('\n'); self.advance()
                    elif esc == 'r':
                        buf.append('\r'); self.advance()
                    elif esc == 't':
                        buf.append('\t'); self.advance()
                    elif esc == 'v':
                        buf.append('\v'); self.advance()
                    elif esc == '\\':
                        buf.append('\\'); self.advance()
                    elif esc == '"':
                        buf.append('"'); self.advance()
                    elif esc == "'":
                        buf.append("'"); self.advance()
                    elif esc == '\n' or esc == '\r':
                        # \ newline -> newline
                        self.advance()
                        # handle \r\n?
                        if esc == '\r' and self.peek() == '\n':
                            self.advance()
                        buf.append('\n')
                    elif esc.isdigit():
                        # \ddd decimal up to 3 digits
                        num = ''
                        for _ in range(3):
                            if self.pos < self.len and self.peek().isdigit():
                                num+=self.peek()
                                self.advance()
                            else:
                                break
                        if num:
                            try:
                                buf.append(chr(int(num)))
                            except:
                                pass
                        else:
                            buf.append(esc)
                    else:
                        # unknown, keep as is? Lua keeps \?
                        buf.append(esc)
                        self.advance()
                else:
                    buf.append(ch)
                    self.advance()
            else:
                # unterminated
                pass
            return ('STRING', ''.join(buf), start_line)

        # number
        if c.isdigit() or (c == '.' and self.peek(1).isdigit()):
            # hex?
            if c == '0' and self.peek(1) in 'xX':
                self.advance(2)
                num_str = ''
                while self.pos < self.len and self.peek() in '0123456789abcdefABCDEF':
                    num_str+=self.peek()
                    self.advance()
                try:
                    val = int(num_str, 16)
                except:
                    val = 0
                return ('NUMBER', float(val), start_line)
            # decimal
            num_str = ''
            has_dot = False
            has_exp = False
            while self.pos < self.len:
                ch = self.peek()
                if ch.isdigit():
                    num_str+=ch
                    self.advance()
                elif ch == '.' and not has_dot:
                    # need to check if '..' ?
                    if self.peek(1) == '.':
                        break
                    has_dot = True
                    num_str+=ch
                    self.advance()
                elif ch in 'eE' and not has_exp:
                    has_exp = True
                    num_str+=ch
                    self.advance()
                    if self.peek() in '+-':
                        num_str+=self.peek()
                        self.advance()
                else:
                    break
            try:
                if '.' in num_str or 'e' in num_str.lower():
                    val = float(num_str)
                else:
                    val = float(int(num_str))
            except:
                val = 0.0
            return ('NUMBER', val, start_line)

        # name or keyword
        if c.isalpha() or c == '_':
            ident = ''
            while self.pos < self.len and (self.peek().isalnum() or self.peek() == '_'):
                ident+=self.peek()
                self.advance()
            if ident in KEYWORDS:
                return (ident, ident, start_line)
            else:
                return ('NAME', ident, start_line)

        # operators -- check multi-char first
        # ... , ==, ~=, <=, >=, .., //
        three = self.text[self.pos:self.pos+3]
        two = self.text[self.pos:self.pos+2]
        if three == '...':
            self.advance(3)
            return ('...', '...', start_line)
        if two in ('==','~=','<=','>=','..','//','<<','>>'):
            self.advance(2)
            return (two, two, start_line)
        # single char
        self.advance()
        return (c, c, start_line)

    def tokenize(self):
        tokens = []
        while True:
            tok = self.next_token()
            tokens.append(tok)
            if tok[0] == 'EOF':
                break
        return tokens

# Parser
# We'll write a recursive descent parser that builds AST nodes as simple tuples/dicts

class ParseError(Exception):
    def __init__(self, msg, line):
        super().__init__(f"{msg} at line {line}")
        self.line = line

class Parser:
    def __init__(self, tokens, filename="<string>"):
        self.tokens = tokens
        self.pos = 0
        self.filename = filename

    def peek(self, offset=0):
        idx = self.pos+offset
        if idx >= len(self.tokens):
            return ('EOF','',0)
        return self.tokens[idx]

    def cur(self):
        return self.peek(0)

    def advance(self):
        t = self.cur()
        self.pos+=1
        return t

    def expect(self, typ):
        t = self.cur()
        if t[0] != typ:
            raise ParseError(f"expected {typ} got {t[0]} ({t[1]})", t[2])
        self.pos+=1
        return t

    def match(self, typ):
        if self.cur()[0]==typ:
            self.pos+=1
            return True
        return False

    # chunk -> block EOF
    def parse_chunk(self):
        block = self.parse_block()
        self.expect('EOF')
        return {'type':'chunk','block':block}

    def parse_block(self):
        stats = []
        while True:
            if self.cur()[0] in ('end','else','elseif','until','EOF'):
                break
            # return is handled separately but also a stat
            if self.cur()[0]=='return':
                ret = self.parse_retstat()
                stats.append(ret)
                # after return, may have ; and then should break? In Lua, return must be last, but we allow following ';' and then check if next is block end; but we will break after return if semicolon maybe
                # Consume optional ;
                if self.cur()[0]==';':
                    self.advance()
                break
            # break
            if self.cur()[0]=='break':
                # break stat
                tok = self.advance()
                stats.append({'type':'break','line':tok[2]})
                # optional ;
                if self.cur()[0]==';':
                    self.advance()
                continue
            # empty ;
            if self.cur()[0]==';':
                self.advance()
                stats.append({'type':'empty'})
                continue
            # try stat
            # Lookahead: if cur is '::'? That's Lua 5.2 goto, ignore.
            st = self.parse_stat()
            if st is None:
                break
            stats.append(st)
            # optional ;
            if self.cur()[0]==';':
                self.advance()
        return {'type':'block','stats':stats}

    def parse_retstat(self):
        tok = self.expect('return')
        exps = []
        if self.cur()[0] not in ('end','else','elseif','until','EOF',';'):
            # Check if next tokens start an exp? If exp starts, parse explist
            # Heuristic: if cur is not a block terminator, try parse explist
            # But need to avoid if cur is something that can't start exp? We'll attempt
            try:
                exps = self.parse_explist()
            except ParseError:
                exps = []
        return {'type':'return','exps':exps,'line':tok[2]}

    def parse_stat(self):
        t = self.cur()
        if t[0]=='do':
            self.advance()
            b = self.parse_block()
            self.expect('end')
            return {'type':'do','block':b,'line':t[2]}
        elif t[0]=='while':
            self.advance()
            exp = self.parse_exp()
            self.expect('do')
            b = self.parse_block()
            self.expect('end')
            return {'type':'while','cond':exp,'block':b,'line':t[2]}
        elif t[0]=='repeat':
            self.advance()
            b = self.parse_block()
            self.expect('until')
            exp = self.parse_exp()
            return {'type':'repeat','block':b,'cond':exp,'line':t[2]}
        elif t[0]=='if':
            return self.parse_if()
        elif t[0]=='for':
            return self.parse_for()
        elif t[0]=='function':
            return self.parse_function_stat()
        elif t[0]=='local':
            return self.parse_local()
        else:
            # Could be assignment or functioncall
            # Need to parse prefixexp and then check if it's assignment or call
            # For assignment, we need varlist '=' explist
            # For functioncall, it's prefixexp
            # The trick: parse prefixexp starting with NAME or '(' etc, then if next token is ',' or '=' we treat as assignment
            # So try to parse as varlist
            # Save pos
            saved = self.pos
            try:
                # Attempt to parse varlist
                # varlist is first var, then {',' var}
                # But var can be NAME or prefixexp '[' exp ']' or prefixexp '.' NAME
                # We'll parse first var as possible prefixexp but check if it's var
                # For simplicity, attempt to parse prefixexp chain for var
                # Then see if next token is ',' or '='
                # If so, it's assignment, else backtrack and parse functioncall/expression statement
                # Actually assignment's left side vars are parsed as vars, not arbitrary exps
                # So we attempt parse var
                first_var = self.parse_var()
                varlist = [first_var]
                while self.cur()[0]==',':
                    self.advance()
                    varlist.append(self.parse_var())
                if self.cur()[0]=='=':
                    self.advance()
                    explist = self.parse_explist()
                    return {'type':'assign','vars':varlist,'exps':explist,'line':t[2]}
                else:
                    # Not assignment, backtrack
                    self.pos = saved
            except ParseError:
                self.pos = saved
                # fall through to functioncall
                pass
            # Try functioncall as stat
            # parse prefixexp
            exp = self.parse_prefixexp()
            # Check if it's a functioncall node
            if exp['type'] in ('call','method_call'):
                return {'type':'call_stat','call':exp,'line':t[2]}
            else:
                raise ParseError(f"unexpected token {t[0]}", t[2])

    def parse_if(self):
        tok = self.expect('if')
        cond = self.parse_exp()
        self.expect('then')
        then_block = self.parse_block()
        elseif_blocks = []
        else_block = None
        while self.cur()[0]=='elseif':
            self.advance()
            econd = self.parse_exp()
            self.expect('then')
            eblock = self.parse_block()
            elseif_blocks.append((econd, eblock))
        if self.cur()[0]=='else':
            self.advance()
            else_block = self.parse_block()
        self.expect('end')
        return {'type':'if','cond':cond,'then':then_block,'elseif':elseif_blocks,'else':else_block,'line':tok[2]}

    def parse_for(self):
        tok = self.expect('for')
        name_tok = self.expect('NAME')
        name = name_tok[1]
        if self.cur()[0]=='=':
            # numeric for
            self.advance()
            start = self.parse_exp()
            self.expect(',')
            end = self.parse_exp()
            step = None
            if self.cur()[0]==',':
                self.advance()
                step = self.parse_exp()
            self.expect('do')
            block = self.parse_block()
            self.expect('end')
            return {'type':'fornum','name':name,'start':start,'end':end,'step':step,'block':block,'line':tok[2]}
        elif self.cur()[0]==',' or self.cur()[0]=='in':
            # generic for
            namelist = [name]
            while self.cur()[0]==',':
                self.advance()
                nt = self.expect('NAME')
                namelist.append(nt[1])
            self.expect('in')
            explist = self.parse_explist()
            self.expect('do')
            block = self.parse_block()
            self.expect('end')
            return {'type':'forin','names':namelist,'exps':explist,'block':block,'line':tok[2]}
        else:
            raise ParseError("invalid for", tok[2])

    def parse_function_stat(self):
        tok = self.expect('function')
        funcname = self.parse_funcname()
        body = self.parse_funcbody()
        return {'type':'funcdef','name':funcname,'body':body,'line':tok[2]}

    def parse_funcname(self):
        # Name {'.' Name} [':' Name]
        first = self.expect('NAME')
        name = {'type':'funcname','base':first[1],'fields':[],'method':None,'line':first[2]}
        while self.cur()[0]=='.':
            self.advance()
            n = self.expect('NAME')
            name['fields'].append(n[1])
        if self.cur()[0]==':':
            self.advance()
            n = self.expect('NAME')
            name['method']=n[1]
        return name

    def parse_funcbody(self):
        self.expect('(')
        parlist = []
        is_vararg = False
        if self.cur()[0]!=')':
            if self.cur()[0]=='...':
                self.advance()
                is_vararg=True
            else:
                # namelist [',' '...']?
                n = self.expect('NAME')
                parlist.append(n[1])
                while self.cur()[0]==',':
                    self.advance()
                    if self.cur()[0]=='...':
                        self.advance()
                        is_vararg=True
                        break
                    else:
                        n = self.expect('NAME')
                        parlist.append(n[1])
        self.expect(')')
        block = self.parse_block()
        self.expect('end')
        return {'type':'funcbody','params':parlist,'vararg':is_vararg,'block':block}

    def parse_local(self):
        tok = self.expect('local')
        if self.cur()[0]=='function':
            self.advance()
            n = self.expect('NAME')
            body = self.parse_funcbody()
            return {'type':'local_func','name':n[1],'body':body,'line':tok[2]}
        else:
            namelist = []
            n = self.expect('NAME')
            namelist.append(n[1])
            while self.cur()[0]==',':
                self.advance()
                n = self.expect('NAME')
                namelist.append(n[1])
            explist = []
            if self.cur()[0]=='=':
                self.advance()
                explist = self.parse_explist()
            return {'type':'local_assign','names':namelist,'exps':explist,'line':tok[2]}

    def parse_var(self):
        # var ::= Name | prefixexp '[' exp ']' | prefixexp '.' Name
        # But to avoid left recursion, we parse as: primary = NAME or '(' exp ')' etc? Actually var starts with NAME, then can have suffixes
        # For simple assignment left side, we can parse NAME, then while next is '.' NAME or '[' exp ']': build indexing.
        # But we also need to allow prefixexp that is already a var? Actually the grammar for var after first is recursive: prefixexp includes var itself. So we need to handle chain.

        # Start with NAME
        # Look ahead: if cur NAME, but next token is not '.' or '[' then it's just NAME var
        # If we have '(' ... ')', that's not var, it's (exp) which is not var (except if exp is var? but '(' exp ')' is not var alone, it's enclosed)
        # So var parsing will be: parse prefixexp's base, then unwind?

        # Simplify: parse NAME token
        # Then while true: if '.' then consume '.' NAME -> build index
        # elif '[' then consume '[' exp ']' -> build index

        # But we must distinguish: if first token is NAME and we have suffixes, it's still var.

        t = self.cur()
        if t[0]!='NAME':
            raise ParseError("expected variable", t[2])
        self.advance()
        node = {'type':'var_name','name':t[1],'line':t[2]}
        while True:
            if self.cur()[0]=='.':
                self.advance()
                n = self.expect('NAME')
                node = {'type':'index','table':node,'key':{'type':'string','value':n[1]},'key_is_string':True,'line':n[2]}
            elif self.cur()[0]=='[':
                self.advance()
                key_exp = self.parse_exp()
                self.expect(']')
                node = {'type':'index','table':node,'key':key_exp,'line':t[2]}
            else:
                break
        return node

    def parse_explist(self):
        exps = [self.parse_exp()]
        while self.cur()[0]==',':
            self.advance()
            exps.append(self.parse_exp())
        return exps

    def parse_exp(self):
        # Use Pratt parsing for binops
        return self.parse_subexp(0)

    # Operator precedence table (lower number lower precedence)
    # Based on Lua manual:
    # or 1, and 2, < > <= >= ~= == 3, .. 4 (right), + - 5, * / % // 6, unary 7, ^ 8 (right)
    BINOPS = {
        'or': (1, 'left'),
        'and': (2, 'left'),
        '<': (3, 'left'),
        '>': (3, 'left'),
        '<=': (3, 'left'),
        '>=': (3, 'left'),
        '~=': (3, 'left'),
        '==': (3, 'left'),
        '..': (4, 'right'),
        '+': (5, 'left'),
        '-': (5, 'left'),
        '*': (6, 'left'),
        '/': (6, 'left'),
        '%': (6, 'left'),
        '//': (6, 'left'),  # Lua 5.3 but include
        '^': (8, 'right'),
    }

    UNOPS = {'not','#','-','~'}

    def parse_subexp(self, min_prec):
        # parse unary
        t = self.cur()
        if t[0] in ('not','#','-','~'):
            # unary
            op = t[0]
            self.advance()
            # unary precedence is 7, so parse subexp with prec 7? Actually unary binds tighter than all except ^? In Lua, unary has higher than * / etc? Let's check: Lua precedence: ^ > unary > * / etc. So unary prec is 7, ^ is 8, so unary should parse with min_prec 7? But to handle right associativity of ^ after unary, we need careful.
            # We'll parse subexp with precedence 7 (or 8?) For simplicity, parse with 7
            exp = self.parse_subexp(7)
            node = {'type':'unop','op':op,'exp':exp,'line':t[2]}
        else:
            node = self.parse_simpleexp()

        # now parse binops while precedence >= min_prec
        while True:
            op_tok = self.cur()
            op = op_tok[0]
            if op not in self.BINOPS:
                break
            prec, assoc = self.BINOPS[op]
            if prec < min_prec:
                break
            self.advance()
            # For next, min_prec = prec+1 if left assoc, prec if right assoc
            next_min = prec+1 if assoc=='left' else prec
            right = self.parse_subexp(next_min)
            node = {'type':'binop','op':op,'left':node,'right':right,'line':op_tok[2]}
        return node

    def parse_simpleexp(self):
        t = self.cur()
        if t[0]=='nil':
            self.advance()
            return {'type':'nil','line':t[2]}
        elif t[0]=='false':
            self.advance()
            return {'type':'false','line':t[2]}
        elif t[0]=='true':
            self.advance()
            return {'type':'true','line':t[2]}
        elif t[0]=='NUMBER':
            self.advance()
            return {'type':'number','value':t[1],'line':t[2]}
        elif t[0]=='STRING':
            self.advance()
            return {'type':'string','value':t[1],'line':t[2]}
        elif t[0]=='...':
            self.advance()
            return {'type':'vararg','line':t[2]}
        elif t[0]=='function':
            self.advance()
            body = self.parse_funcbody()
            return {'type':'function','body':body,'line':t[2]}
        elif t[0]=='{':
            return self.parse_tableconstructor()
        elif t[0]=='(':
            self.advance()
            exp = self.parse_exp()
            self.expect(')')
            return {'type':'paren','exp':exp,'line':t[2]}
        else:
            # prefixexp
            return self.parse_prefixexp()

    def parse_prefixexp(self):
        # prefixexp ::= var | functioncall | '(' exp ')'
        # var already handled partly, but we need to parse functioncall chain
        # We'll start with primary: NAME or '(' exp ')'
        t = self.cur()
        if t[0]=='NAME':
            self.advance()
            node = {'type':'var_name','name':t[1],'line':t[2]}
        elif t[0]=='(':
            self.advance()
            exp = self.parse_exp()
            self.expect(')')
            node = {'type':'paren','exp':exp,'line':t[2]}
        else:
            raise ParseError(f"unexpected symbol near '{t[1]}'", t[2])

        # Now loop over suffixes: . NAME, [ exp ], : NAME args, args
        while True:
            if self.cur()[0]=='.':
                self.advance()
                n = self.expect('NAME')
                node = {'type':'index','table':node,'key':{'type':'string','value':n[1]},'line':n[2]}
            elif self.cur()[0]=='[':
                self.advance()
                key = self.parse_exp()
                self.expect(']')
                node = {'type':'index','table':node,'key':key,'line':t[2]}
            elif self.cur()[0]==':':
                self.advance()
                n = self.expect('NAME')
                args = self.parse_args()
                node = {'type':'method_call','object':node,'method':n[1],'args':args,'line':n[2]}
            elif self.cur()[0] in ('(','{','STRING'):
                args = self.parse_args()
                node = {'type':'call','func':node,'args':args,'line':t[2]}
            else:
                break
        return node

    def parse_args(self):
        t = self.cur()
        if t[0]=='(':
            self.advance()
            explist = []
            if self.cur()[0]!=')':
                explist = self.parse_explist()
            self.expect(')')
            return {'type':'args','explist':explist,'line':t[2]}
        elif t[0]=='{':
            tbl = self.parse_tableconstructor()
            return {'type':'args','explist':[tbl],'line':t[2]}
        elif t[0]=='STRING':
            self.advance()
            return {'type':'args','explist':[{'type':'string','value':t[1],'line':t[2]}],'line':t[2]}
        else:
            raise ParseError("expected args", t[2])

    def parse_tableconstructor(self):
        tok = self.expect('{')
        fields = []
        while self.cur()[0]!='}':
            if self.cur()[0]=='EOF':
                raise ParseError("unexpected <eof>", tok[2])
            field = self.parse_field()
            fields.append(field)
            if self.cur()[0] in (',',';'):
                self.advance()
            else:
                # if not } then continue? Could be missing sep
                pass
        self.expect('}')
        return {'type':'table','fields':fields,'line':tok[2]}

    def parse_field(self):
        t = self.cur()
        # '[' exp ']' '=' exp
        if t[0]=='[':
            self.advance()
            key = self.parse_exp()
            self.expect(']')
            self.expect('=')
            val = self.parse_exp()
            return {'type':'field','key':key,'value':val}
        # NAME '=' exp
        if t[0]=='NAME' and self.peek(1)[0]=='=':
            name = t[1]
            self.advance()
            self.advance()
            val = self.parse_exp()
            return {'type':'field','key':{'type':'string','value':name},'value':val,'is_name':True}
        # exp
        exp = self.parse_exp()
        return {'type':'field','key':None,'value':exp}

