class Environment:
    def __init__(self, outer=None):
        self.vars = {}
        self.outer = outer

    def get(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.outer:
            return self.outer.get(name)
        return nil

    def set(self, name, value, local=False):
        if local or name in self.vars or self.outer is None:
            self.vars[name] = value
        else:
            # check if exists in outer
            # we need to find where defined
            env = self
            while env:
                if name in env.vars:
                    env.vars[name]=value
                    return
                env = env.outer
            # not found, set in current? Actually set global in root
            # Find root
            root = self
            while root.outer:
                root = root.outer
            root.vars[name]=value

    def set_local(self, name, value):
        self.vars[name]=value

