                        try:
                            out.append(('%'+ch) % float(args[arg_idx]))
                        except:
                            out.append(str(args[arg_idx]))
                        arg_idx+=1
                        i+=1
                    elif ch=='q':
                        if arg_idx>=len(args):
                            raise LuaError("bad argument")
                        # %q quotes string
                        v=args[arg_idx]
                        if isinstance(v,str):
                            out.append('"%s"' % v.replace('"','\\"').replace('\n','\\n'))
