                            out.append(lua_tostring(v))
                        arg_idx+=1
                        i+=1
                    else:
                        # unsupported, keep
                        out.append('%'+ch)
                        i+=1
                else:
                    out.append(fmt[i])
                    i+=1
            return "".join(out)

