        # Returns True if parsed as flag, None if not
        # flags: fold, cse, dce, narrow, loop, fwd, dse, abc, sink, fuse, fma
        valid_flags = {'fold','cse','dce','narrow','loop','fwd','dse','abc','sink','fuse','fma'}
        # Also params handled elsewhere
        # flag_str can be like "fold", "+fold", "-fold", "fma", etc.
        # Also can be like "3" etc. handled elsewhere
        # For flag with +/-, strip
        s = flag_str
        if s=='':
            return None
        sign = None
        if s[0]=='+':
            sign='+'
            core=s[1:]
        elif s[0]=='-':
            sign='-'
            core=s[1:]
        else:
            core=s
            sign=None
        if core in valid_flags:
            if sign=='+' or sign is None:
                # enable
                self.jit_flags.add(core)
            else:
                # disable
                if core in self.jit_flags:
                    self.jit_flags.remove(core)
            return True
        # Could also be param?
        # param with = handled elsewhere
        return None

    def set_opt_level(self, lvl):
        # Set flags according to level
        # level 0: no flags
        # level 1: fold cse dce
        # level 2: fold cse dce narrow loop
        # level 3: fold cse dce fwd dse narrow loop abc sink fuse
        # default is 3
        self.jit_flags = set()
        if lvl>=1:
            self.jit_flags.update(['fold','cse','dce'])
        if lvl>=2:
            self.jit_flags.update(['narrow','loop'])
        if lvl>=3:
            self.jit_flags.update(['fwd','dse','abc','sink','fuse'])
        # fma only if explicitly enabled
        # Keep fma if previously enabled? No, level overrides and fma disabled unless enabled explicitly after?
        # According to earlier tests: -O+fma then -O3 should disable fma (we observed). So set level should clear fma.
        # So fma not included in any level.

    def parse_O(self, opt_string):
        # opt_string may be empty? For -O alone, opt_string == ""? In our CLI parsing, -O alone has no attached opt, we treat as default level 3.
        # If opt_string is None or "", set default 3
        if not opt_string:
            self.set_opt_level(3)
            return
        # Split by comma
        parts = opt_string.split(',')
        for part in parts:
            if part=='':
                # empty part -> error "bad argument #1 to '?' (string expected, got nil)" observed for -O, case
                raise LuaError(f"bad argument #1 to '?' (string expected, got nil)", is_O_comma_error=True)
            # part may be like "3", "fold", "+fold", "-fold", "maxtrace=100"
            # Try to parse as level if it's a digit single char? Actually level can be 0-? Could be multi-digit? But we only support 0-3.
            # If part is digit string and length 1 and first char digit and rest not? Eg "0","1","2","3"
            # But also "3" could be part of comma list like "3,cse" -> should set level to 3 then enable cse
            # According to doc: You can either use this option multiple times (like -Ocse -O-dce -Ohotloop=10) or separate several settings with a comma (like -O+cse,-dce,hotloop=10). The settings are applied from left to right, and later settings override earlier ones. You can freely mix the three forms, but note that setting an optimization level overrides all earlier flags.
            # So parsing left to right: if part is level (digit), set level (overrides all earlier flags)
            # Else if part is flag or +flag or -flag, set accordingly
            # Else if part is param=value, set param
            # Else error "unknown or malformed optimization flag"
            # Note: flag without + is enable? According to tests, -Ocse enables cse (even if previously disabled)
            # And -O+flag also enables, -O-flag disables

            # Check if part is number (level)
            if part.isdigit() and len(part)==1:
                lvl = int(part)
                self.set_opt_level(lvl)
                continue
            # Also check if part is number with more digits? e.g., "10" is not valid level, would be unknown flag
            # So only single digit 0-9? But we only accept 0-3, others error? Let's test -O4? We haven't tested.
            # For now, if part is digits but not single digit, treat as unknown flag error
            # Try flag
            if self.try_parse_O_flag(part):
                continue
            # Try param=value
            if '=' in part:
                pname, pval = part.split('=',1)
                if pname in self.jit_params:
                    if pval=='':
                        # empty value allowed? earlier we saw -Ohotloop= succeeded (printed 1). So allow empty?
                        # For -O, hotloop= with empty value allowed (maybe sets to 0?). We'll allow and ignore.
                        continue
                    try:
                        # must be integer >=0
                        if pval.startswith('-'):
                            raise ValueError
                        iv = int(pval)
                        if iv<0:
                            raise ValueError
                        # also check if param expects non-zero? For maxtrace=0 we allowed (printed 1). So allow 0
                        self.jit_params[pname]=iv
                        continue
                    except:
                        raise LuaError(f"unknown or malformed optimization flag '{part}'")
                else:
                    raise LuaError(f"unknown or malformed optimization flag '{part}'")
            # If not matched, error
            raise LuaError(f"unknown or malformed optimization flag '{part}'")

    def load_chunk(self, code, filename, modname=None):
        # handle shebang
        if code.startswith('#!'):
            # remove first line
            idx = code.find('\n')
            if idx!=-1:
                code = code[idx+1:]
        lexer = Lexer(code, filename)
        tokens = lexer.tokenize()
        parser = Parser(tokens, filename)
        try:
            ast = parser.parse_chunk()
        except ParseError as e:
            raise LuaError(f"{filename}:{e.line}: {e}", line=e.line)
        return ast

    def execute_chunk(self, ast, env=None):
        if env is None:
            env = self.globals
        self.push_env(Environment(outer=env if isinstance(env, Environment) else None))
        # Actually we need to use env as outer for new env
        # The block's execution
        try:
            result = self.exec_block(ast['block'])
            # result is return values? If no return, nil
            return nil
        except ReturnException as re:
            # return values
            vals = re.values
            if len(vals)==0:
                return nil
            if len(vals)==1:
                return vals[0]
            return tuple(vals)
        finally:
            self.pop_env()

    def exec_block(self, block):
        for stat in block['stats']:
            self.exec_stat(stat)

    def exec_stat(self, stat):
        t = stat['type']
        if t=='empty':
            return
        elif t=='break':
            raise BreakException()
        elif t=='do':
            self.push_env(Environment(outer=self.current_env()))
            try:
                self.exec_block(stat['block'])
            finally:
                self.pop_env()
        elif t=='while':
            while is_truthy(self.eval_exp(stat['cond'])):
                try:
                    self.push_env(Environment(outer=self.current_env()))
                    self.exec_block(stat['block'])
                    self.pop_env()
                except BreakException:
                    self.pop_env()
                    break
        elif t=='repeat':
            self.push_env(Environment(outer=self.current_env()))
            try:
                while True:
                    self.exec_block(stat['block'])
                    cond = self.eval_exp(stat['cond'])
                    if is_truthy(cond):
                        break
            except BreakException:
                pass
            finally:
                self.pop_env()
        elif t=='if':
            cond = self.eval_exp(stat['cond'])
            if is_truthy(cond):
                self.push_env(Environment(outer=self.current_env()))
                try:
                    self.exec_block(stat['then'])
                finally:
                    self.pop_env()
            else:
                executed=False
                for econd, eblock in stat['elseif']:
                    c = self.eval_exp(econd)
                    if is_truthy(c):
                        self.push_env(Environment(outer=self.current_env()))
                        try:
                            self.exec_block(eblock)
                        finally:
                            self.pop_env()
                        executed=True
                        break
                if not executed and stat['else'] is not None:
                    self.push_env(Environment(outer=self.current_env()))
                    try:
                        self.exec_block(stat['else'])
                    finally:
                        self.pop_env()
        elif t=='fornum':
            # evaluate start, end, step
            start = self.eval_exp(stat['start'])
            end = self.eval_exp(stat['end'])
            step = self.eval_exp(stat['step']) if stat['step'] else 1.0
            # convert to numbers
            try:
                s = float(start) if isinstance(start,(int,float)) else float(start)
                e = float(end) if isinstance(end,(int,float)) else float(end)
                st = float(step) if isinstance(step,(int,float)) else float(step)
            except:
                raise LuaError("'for' initial value must be a number")
            name = stat['name']
            self.push_env(Environment(outer=self.current_env()))
            self.current_env().set_local(name, s)
            try:
                # loop
                while (st>0 and s<=e) or (st<0 and s>=e):
                    self.current_env().set_local(name, s)
                    try:
                        self.exec_block(stat['block'])
                    except BreakException:
                        break
                    s += st
                # end
            finally:
                self.pop_env()
        elif t=='forin':
            # for namelist in explist do block
            # explist should return 1-3 values: iterator, state, initial var
            explist_vals = []
            for exp in stat['exps']:
                v = self.eval_exp(exp)
                if isinstance(v, tuple):
                    explist_vals.extend(v)
                else:
                    explist_vals.append(v)
            # get iterator, state, var
            f = explist_vals[0] if len(explist_vals)>0 else nil
            s = explist_vals[1] if len(explist_vals)>1 else nil
            var = explist_vals[2] if len(explist_vals)>2 else nil

            self.push_env(Environment(outer=self.current_env()))
            # set initial var
            # generic for loop semantics: for loop calls iterator(state, var) each iteration, getting new var and values
            # For simplicity, we handle common case: ipairs or pairs returning function
            # We'll implement loop

            # Initialize control variable
            control = var
            while True:
                # call iterator
                if isinstance(f, LuaBuiltin):
                    res = f.pyfunc(s, control)
                elif isinstance(f, LuaFunction) or isinstance(f, dict):
                    res = self.call_function(f, [s, control])
                else:
                    raise LuaError(f"attempt to call a {self.globals.get('type').pyfunc(f)} value")

                # res should be next var or nil, plus other values
                if isinstance(res, tuple):
                    if len(res)==0 or res[0] is nil:
                        break
                    next_var = res[0]
                    values = res[1:]
                else:
                    if res is nil:
                        break
                    next_var = res
                    values = []

                # assign namelist
                names = stat['names']
                # first name is control var
                self.current_env().set_local(names[0], next_var)
                for i, n in enumerate(names[1:]):
                    if i < len(values):
                        self.current_env().set_local(n, values[i])
                    else:
                        self.current_env().set_local(n, nil)
                control = next_var
                try:
                    self.exec_block(stat['block'])
                except BreakException:
                    break
            self.pop_env()
        elif t=='funcdef':
            # funcname: base, fields, method
            funcname = stat['name']
            body = stat['body']
            # create function closure
            closure = LuaFunction(body, self.current_env())
            # assign
            # base table
            # get base var
            base_name = funcname['base']
            tbl = self.current_env().get(base_name)
            if tbl is nil:
                # create table? Actually if assigning to global function that doesn't exist, base is global
                # For simplicity, if tbl is nil, create? Actually function name could be global
                # If fields empty and no method, it's just global var
                if not funcname['fields'] and funcname['method'] is None:
                    self.current_env().set(base_name, closure)
                else:
                    # need to create intermediate tables?
                    # For now, assume base exists as table or create new table and assign to global
                    tbl = LuaTable()
                    self.current_env().set(base_name, tbl)
                    # then proceed with fields
                    cur = tbl
                    for field in funcname['fields'][:-1]:
                        nxt = cur.rawget(field) if isinstance(cur, LuaTable) else nil
                        if nxt is nil:
                            nxt = LuaTable()
                            cur.rawset(field, nxt)
                        cur = nxt
                    # last field or method
                    if funcname['fields']:
                        last = funcname['fields'][-1]
                        if funcname['method'] is None:
                            cur.rawset(last, closure)
                        else:
                            # method: cur[last] is table, then set method name inside
                            method_tbl = cur.rawget(last) if isinstance(cur, LuaTable) else nil
                            if method_tbl is nil:
                                method_tbl = LuaTable()
                                cur.rawset(last, method_tbl)
                            method_tbl.rawset(funcname['method'], closure)
                            # Also set up self?
                    else:
                        # no fields, but method present: base:method => base[method]=func with self param
                        if funcname['method']:
                            if isinstance(tbl, LuaTable):
                                tbl.rawset(funcname['method'], closure)
            else:
                # base exists
                cur = tbl
                if not funcname['fields'] and funcname['method'] is None:
                    self.current_env().set(base_name, closure)
                else:
                    # navigate fields
                    for field in funcname['fields'][:-1]:
                        nxt = cur.rawget(field) if isinstance(cur, LuaTable) else nil
                        if nxt is nil:
                            nxt = LuaTable()
                            cur.rawset(field, nxt)
                        cur = nxt
                    if funcname['fields']:
                        last = funcname['fields'][-1]
                        if funcname['method'] is None:
                            cur.rawset(last, closure)
                        else:
                            method_tbl = cur.rawget(last) if isinstance(cur, LuaTable) else nil
                            if method_tbl is nil:
                                method_tbl = LuaTable()
                                cur.rawset(last, method_tbl)
                            method_tbl.rawset(funcname['method'], closure)
                    else:
                        # method on base
                        if funcname['method']:
                            cur.rawset(funcname['method'], closure)

        elif t=='local_func':
            name = stat['name']
            body = stat['body']
            closure = LuaFunction(body, self.current_env())
            self.current_env().set_local(name, closure)
        elif t=='local_assign':
            names = stat['names']
            exps = stat['exps']
            values = []
            for exp in exps:
                v = self.eval_exp(exp)
                if isinstance(v, tuple):
                    # unpack first value? Actually for assignment, if last exp returns multiple values, it should be expanded
                    # Check if it's last exp
                    if exp == exps[-1]:
                        values.extend(v)
                    else:
                        values.append(v[0] if len(v)>0 else nil)
                else:
                    values.append(v)
            for i, name in enumerate(names):
                if i < len(values):
                    self.current_env().set_local(name, values[i])
                else:
                    self.current_env().set_local(name, nil)
        elif t=='assign':
            varlist = stat['vars']
            explist = stat['exps']
            values = []
            for exp in explist:
                v = self.eval_exp(exp)
                if isinstance(v, tuple):
                    if exp == explist[-1]:
                        values.extend(v)
                    else:
                        values.append(v[0] if len(v)>0 else nil)
                else:
                    values.append(v)
            for i, var in enumerate(varlist):
                val = values[i] if i < len(values) else nil
                self.assign_var(var, val)
        elif t=='call_stat':
            self.eval_exp(stat['call'])
        elif t=='return':
            vals = []
            for exp in stat['exps']:
                v = self.eval_exp(exp)
                if isinstance(v, tuple):
                    # if last exp, expand
                    if exp == stat['exps'][-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if len(v)>0 else nil)
                else:
                    vals.append(v)
            raise ReturnException(vals)
        else:
            raise LuaError(f"unhandled stat {t}")

    def assign_var(self, var_node, value):
        if var_node['type']=='var_name':
            name = var_node['name']
            # find where to set: search env stack for existing var, else set global
            self.current_env().set(name, value)
        elif var_node['type']=='index':
            tbl = self.eval_exp(var_node['table'])
            key = var_node['key']
            # key may be string literal node? We handled earlier key as {'type':'string','value':...} for '.' case
            if isinstance(key, dict) and key['type']=='string':
                k = key['value']
            else:
                k = self.eval_exp(key)
            if not isinstance(tbl, LuaTable):
                # check metatable __newindex?
                # For simplicity, error if not table
                raise LuaError(f"attempt to index a {self.globals.get('type').pyfunc(tbl)} value")
            res = tbl.set(k, value)
            if isinstance(res, LuaMetaCall):
                # call metamethod
                self.call_function(res.func, list(res.args))
            # else done
        else:
            raise LuaError("invalid assignment")

    def eval_exp(self, node):
        t = node['type']
        if t=='nil':
            return nil
        elif t=='false':
            return False
        elif t=='true':
            return True
        elif t=='number':
            return node['value']
        elif t=='string':
            return node['value']
        elif t=='vararg':
            # return varargs from stack
            if self.vararg_stack:
                return tuple(self.vararg_stack[-1])
            return nil
        elif t=='var_name':
            name = node['name']
            v = self.current_env().get(name)
            return v
        elif t=='index':
            tbl = self.eval_exp(node['table'])
            if isinstance(node['key'], dict) and node['key']['type']=='string':
                key = node['key']['value']
            else:
                key = self.eval_exp(node['key'])
            if isinstance(tbl, LuaTable):
                v = tbl.get(key)
                if isinstance(v, LuaMetaCall):
                    # call __index metamethod
                    res = self.call_function(v.func, list(v.args))
                    if isinstance(res, tuple):
                        return res[0] if res else nil
                    return res
                return v
            elif isinstance(tbl, str):
                # string indexing? In Lua, "abc":upper() etc, also string library as metatable
                # For indexing string with string key, look up string library?
                # e.g., ("hello"):upper() -> should find upper in string library metatable
                # We'll handle: if key is string, look for method in string library
                # Also allow string indexing? Actually "hello"[1] not valid
                # For method, we will return builtin that binds?
                # Simplified: check string library table
                str_lib = self.globals.get('string')
                if isinstance(str_lib, LuaTable):
                    meth = str_lib.rawget(key)
                    if meth is not nil:
                        return meth
                return nil
            else:
                raise LuaError(f"attempt to index a {self.globals.get('type').pyfunc(tbl)} value")
        elif t=='call':
            func = self.eval_exp(node['func'])
            args = []
            for arg_exp in node['args']['explist']:
                v = self.eval_exp(arg_exp)
                if isinstance(v, tuple):
                    # if last arg, expand
                    if arg_exp == node['args']['explist'][-1]:
                        args.extend(v)
                    else:
                        args.append(v[0] if len(v)>0 else nil)
                else:
                    args.append(v)
            return self.call_function(func, args)
        elif t=='method_call':
            obj = self.eval_exp(node['object'])
            method_name = node['method']
            # get method from object
            if isinstance(obj, LuaTable):
                meth = obj.get(method_name)
                if isinstance(meth, LuaMetaCall):
                    meth = self.call_function(meth.func, list(meth.args))
            elif isinstance(obj, str):
                str_lib = self.globals.get('string')
                if isinstance(str_lib, LuaTable):
                    meth = str_lib.rawget(method_name)
                else:
                    meth = nil
            else:
                meth = nil
            # first arg is object (self)
            args = [obj]
            for arg_exp in node['args']['explist']:
                v = self.eval_exp(arg_exp)
                if isinstance(v, tuple):
                    if arg_exp == node['args']['explist'][-1]:
                        args.extend(v)
                    else:
                        args.append(v[0] if len(v)>0 else nil)
                else:
                    args.append(v)
            return self.call_function(meth, args)
        elif t=='paren':
            return self.eval_exp(node['exp'])
        elif t=='function':
            return LuaFunction(node['body'], self.current_env())
        elif t=='table':
            tbl = LuaTable()
            # fields
            array_idx = 1
            for field in node['fields']:
                if field['key'] is None:
                    # array part
                    v = self.eval_exp(field['value'])
                    if isinstance(v, tuple):
                        # if last field and value returns multiple, expand?
                        # In Lua, table constructor with multiple returns? For simplicity, if value is multiple, use first?
                        # Actually for {func()} where func returns multiple values, all values are inserted as array items?
                        # We'll expand if tuple
                        for vv in v:
                            tbl.rawset(array_idx, vv)
                            array_idx+=1
                    else:
                        tbl.rawset(array_idx, v)
                        array_idx+=1
                else:
                    k = self.eval_exp(field['key'])
                    v = self.eval_exp(field['value'])
                    tbl.rawset(k, v)
            return tbl
        elif t=='binop':
            left = self.eval_exp(node['left'])
            right = self.eval_exp(node['right'])
            op = node['op']
            return self.eval_binop(op, left, right, node['line'])
        elif t=='unop':
            exp = self.eval_exp(node['exp'])
            op = node['op']
            return self.eval_unop(op, exp)
        else:
            raise LuaError(f"unhandled exp {t}")

    def eval_binop(self, op, left, right, line):
        # handle metamethods later
        # coerce numbers?
        def to_number(v):
            if isinstance(v, (int,float)):
                return float(v)
            if isinstance(v, str):
                try:
                    return float(v.strip())
                except:
                    return None
            return None

        if op in ('+','-','*','/','%','^','//'):
            ln = to_number(left)
            rn = to_number(right)
            if ln is None or rn is None:
                raise LuaError(f"attempt to perform arithmetic on a {self.globals.get('type').pyfunc(left)} value")
            if op=='+':
                return ln+rn
            elif op=='-':
                return ln-rn
            elif op=='*':
                return ln*rn
            elif op=='/':
                return ln/rn
            elif op=='%':
                # Lua % is modulo
                return ln % rn
            elif op=='^':
                return ln ** rn
            elif op=='//':
                # floor division
                return math.floor(ln/rn)
        elif op=='..':
            # concat
            def to_str(v):
                if isinstance(v, str):
                    return v
                if isinstance(v, (int,float)):
                    if isinstance(v,float) and v.is_integer():
                        return str(int(v))
                    return ('%.14g' % v)
                raise LuaError(f"attempt to concatenate a {self.globals.get('type').pyfunc(v)} value")
            try:
                return to_str(left)+to_str(right)
            except LuaError as e:
                raise
        elif op in ('==','~='):
            eq = self.lua_equal(left,right)
            if op=='==':
                return eq
            else:
                return not eq
        elif op in ('<','>','<=','>='):
            # compare numbers or strings
            if isinstance(left, (int,float)) and isinstance(right, (int,float)):
                lv = float(left); rv = float(right)
                if op=='<': return lv<rv
                if op=='>': return lv>rv
                if op=='<=': return lv<=rv
                if op=='>=': return lv>=rv
            elif isinstance(left, str) and isinstance(right, str):
                if op=='<': return left<right
                if op=='>': return left>right
                if op=='<=': return left<=right
                if op=='>=': return left>=right
            else:
                raise LuaError(f"attempt to compare {self.globals.get('type').pyfunc(left)} with {self.globals.get('type').pyfunc(right)}")
        elif op in ('and','or'):
            if op=='and':
                if is_falsy(left):
                    return left
                else:
                    return right
            else: # or
                if is_truthy(left):
                    return left
                else:
                    return right
        raise LuaError(f"unsupported binop {op}")

    def eval_unop(self, op, exp):
        if op=='-':
            # number
            if isinstance(exp, (int,float)):
                return -float(exp)
            if isinstance(exp, str):
                try:
                    return -float(exp.strip())
                except:
                    pass
            raise LuaError(f"attempt to perform arithmetic on a {self.globals.get('type').pyfunc(exp)} value")
        elif op=='not':
            return not is_truthy(exp)
        elif op=='#':
            if isinstance(exp, str):
                return float(len(exp))
            if isinstance(exp, LuaTable):
                # length operator: #table returns length of array part until first nil
                # approximate: count consecutive non-nil from 1
                length=0
                for i, v in enumerate(exp.array):
                    if v is nil:
                        break
                    length=i+1
                # also check hash for integer keys beyond? For simplicity return length
                return float(length)
            raise LuaError(f"attempt to get length of a {self.globals.get('type').pyfunc(exp)} value")
        elif op=='~':
