        if code.startswith('#!'):
            idx=code.find('\\n')
            if idx!=-1:
                code=code[idx+1:]
        lex=Lexer(code)
        toks=lex.tokenize()
        parser=Parser(toks)
        try:
            ast=parser.parse_chunk()
        except LuaError as e:
            # format as Lua error with file:line
            # e.msg already contains line info
            raise LuaError(f"{filename}: {e.msg}")
        return ast
