class LuaTable:
    def __init__(self):
        self.array = []
        self.hash = {}
        self.metatable = None
    def rawget(self, key):
        if isinstance(key, float) and key.is_integer():
            key = int(key)
        if isinstance(key, int) and key>=1:
            if key <= len(self.array):
                v = self.array[key-1]
                if v is not None:
                    return v
            return self.hash.get(key, nil)
        return self.hash.get(key, nil)
    def rawset(self, key, value):
        if isinstance(key, float) and key.is_integer():
            key = int(key)
        if isinstance(key, int) and key>=1:
            if key <= len(self.array):
                if value is nil:
                    self.array[key-1] = nil
                else:
                    self.array[key-1] = value
                while self.array and self.array[-1] is nil:
                    self.array.pop()
                return
            else:
                if key == len(self.array)+1 and value is not nil:
                    self.array.append(value)
                    return
        if value is nil:
            if key in self.hash:
                del self.hash[key]
            if isinstance(key,int) and 1 <= key <= len(self.array):
                self.array[key-1]=nil
                while self.array and self.array[-1] is nil:
                    self.array.pop()
        else:
            self.hash[key]=value
    def get(self, key):
        v = self.rawget(key)
        if v is not nil:
            return v
        mt = self.metatable
        if mt is not None:
            idx = mt.rawget('__index')
            if idx is not nil:
                if isinstance(idx, LuaTable):
                    return idx.get(key)
                elif isinstance(idx, (LuaBuiltin, LuaFunction)):
                    # call metamethod via calling mechanism is handled outside
                    # return marker
                    return LuaMetaCall(idx, self, key)
        return nil
    def set(self, key, value):
        ev = self.rawget(key)
        if ev is not nil:
            self.rawset(key, value)
            return None
        mt = self.metatable
        if mt is not None:
            nidx = mt.rawget('__newindex')
            if nidx is not nil:
                if isinstance(nidx, LuaTable):
                    nidx.set(key, value)
                    return None
                else:
                    return LuaMetaCall(nidx, self, key, value)
        self.rawset(key, value)
        return None

