# Lexer
class Lexer:
    def __init__(self, text):
        self.text=text
        self.pos=0
        self.line=1
        self.len=len(text)
    def peek(self, n=0):
        p=self.pos+n
        if p>=self.len:
            return ''
        return self.text[p]
    def advance(self, n=1):
        for _ in range(n):
            if self.pos>=self.len:
                return
            c=self.text[self.pos]
            self.pos+=1
            if c=='\\n':
                self.line+=1
    def skip(self):
        while True:
            if self.pos>=self.len:
                return
            c=self.peek()
            if c in ' \\t\\r\\n\\f\\v':
                self.advance()
                continue
            if c=='-' and self.peek(1)=='-':
                self.advance(2)
                if self.peek()=='[':
                    # long comment?
                    j=self.pos
                    eq=0
                    while j<self.len and self.text[j]=='=':
                        eq+=1; j+=1
                    if j<self.len and self.text[j]=='[':
                        self.pos=j+1
                        closing=']'+'='*eq+']'
                        idx=self.text.find(closing, self.pos)
                        if idx==-1:
                            self.pos=self.len
                            return
                        self.pos=idx+len(closing)
                        continue
                # short comment
                while self.pos<self.len and self.peek() not in '\\n\\r':
                    self.advance()
                continue
            break
    def next(self):
        self.skip()
        if self.pos>=self.len:
            return ('EOF','',self.line)
        c=self.peek()
        sl=self.line
        if c=='[':
            j=self.pos+1
            eq=0
            while j<self.len and self.text[j]=='=':
                eq+=1; j+=1
            if j<self.len and self.text[j]=='[':
                self.pos=j+1
                closing=']'+'='*eq+']'
                idx=self.text.find(closing, self.pos)
                if idx==-1:
                    content=self.text[self.pos:]
                    self.pos=self.len
                else:
                    content=self.text[self.pos:idx]
                    self.pos=idx+len(closing)
                if content.startswith('\\n') or content.startswith('\\r'):
                    # strip first newline
                    if content.startswith('\\r\\n'):
                        content=content[2:]
                    elif content.startswith('\\n') or content.startswith('\\r'):
                        content=content[1:]
                return ('STRING', content, sl)
            self.advance()
            return ('[','[',sl)
        if c==']':
            self.advance()
            return (']',']',sl)
        if c=='"' or c=="'":
            quote=c
            self.advance()
            buf=[]
            while self.pos<self.len:
                ch=self.peek()
                if ch==quote:
                    self.advance()
                    break
                if ch=='\\\\':
                    self.advance()
                    if self.pos>=self.len:
                        break
                    esc=self.peek()
                    if esc=='a': buf.append('\\a'); self.advance()
                    elif esc=='b': buf.append('\\b'); self.advance()
                    elif esc=='f': buf.append('\\f'); self.advance()
                    elif esc=='n': buf.append('\\n'); self.advance()
                    elif esc=='r': buf.append('\\r'); self.advance()
                    elif esc=='t': buf.append('\\t'); self.advance()
                    elif esc=='v': buf.append('\\v'); self.advance()
                    elif esc=='\\\\': buf.append('\\\\'); self.advance()
                    elif esc=='"': buf.append('"'); self.advance()
                    elif esc=="'": buf.append("'"); self.advance()
                    elif esc=='\\n' or esc=='\\r':
                        self.advance()
                        if esc=='\\r' and self.peek()=='\\n':
                            self.advance()
                        buf.append('\\n')
                    elif esc.isdigit():
                        num=''
                        for _ in range(3):
                            if self.pos<self.len and self.peek().isdigit():
                                num+=self.peek(); self.advance()
                            else:
                                break
                        if num:
                            try:
                                buf.append(chr(int(num)))
                            except:
                                pass
                        else:
                            buf.append(esc)
                    else:
                        buf.append(esc); self.advance()
                else:
                    buf.append(ch); self.advance()
            return ('STRING', ''.join(buf), sl)
        if c.isdigit() or (c=='.' and self.peek(1).isdigit()):
            if c=='0' and self.peek(1) in 'xX':
                self.advance(2)
                hs=''
                while self.pos<self.len and self.peek() in '0123456789abcdefABCDEF':
                    hs+=self.peek(); self.advance()
                try:
                    v=int(hs,16)
                except:
                    v=0
                return ('NUMBER', float(v), sl)
            num=''
            has_dot=False
            has_exp=False
            while self.pos<self.len:
                ch=self.peek()
                if ch.isdigit():
                    num+=ch; self.advance()
                elif ch=='.' and not has_dot:
                    if self.peek(1)=='.':
                        break
                    has_dot=True; num+=ch; self.advance()
                elif ch in 'eE' and not has_exp:
                    has_exp=True; num+=ch; self.advance()
                    if self.peek() in '+-':
                        num+=self.peek(); self.advance()
