                    break
            try:
                if '.' in num or 'e' in num.lower():
                    v=float(num)
                else:
                    v=float(int(num))
            except:
                v=0.0
            return ('NUMBER', v, sl)
        if c.isalpha() or c=='_':
            ident=''
            while self.pos<self.len and (self.peek().isalnum() or self.peek()=='_'):
                ident+=self.peek(); self.advance()
            keywords={'and','break','do','else','elseif','end','false','for','function','if','in','local','nil','not','or','repeat','return','then','true','until','while'}
            if ident in keywords:
                return (ident, ident, sl)
            return ('NAME', ident, sl)
        three=self.text[self.pos:self.pos+3]
        two=self.text[self.pos:self.pos+2]
        if three=='...':
            self.advance(3)
            return ('...','...',sl)
        if two in ('==','~=','<=','>=','..','//','<<','>>'):
            self.advance(2)
            return (two,two,sl)
