    def cur(self):
        return self.peek(0)
    def advance(self):
        t=self.cur()
        self.pos+=1
        return t
    def expect(self, typ):
        t=self.cur()
        if t[0]!=typ:
            raise LuaError(f"{typ} expected near '{t[1]}' at line {t[2]}")
        self.pos+=1
        return t
    def match(self, typ):
        if self.cur()[0]==typ:
            self.pos+=1
            return True
        return False
    def parse_chunk(self):
        block=self.parse_block()
        self.expect('EOF')
        return {'type':'chunk','block':block}
    def parse_block(self):
        stats=[]
        while True:
            if self.cur()[0] in ('end','else','elseif','until','EOF'):
                break
            if self.cur()[0]=='return':
                stats.append(self.parse_return())
                if self.cur()[0]==';':
                    self.advance()
                break
            if self.cur()[0]=='break':
                tok=self.advance()
                stats.append({'type':'break','line':tok[2]})
                if self.cur()[0]==';':
                    self.advance()
                continue
            if self.cur()[0]==';':
                self.advance()
                continue
            st=self.parse_stat()
            if st:
                stats.append(st)
            if self.cur()[0]==';':
                self.advance()
