    def parse_return(self):
        tok=self.expect('return')
        exps=[]
        if self.cur()[0] not in ('end','else','elseif','until','EOF',';'):
            try:
                exps=self.parse_explist()
            except:
                exps=[]
        return {'type':'return','exps':exps,'line':tok[2]}
    def parse_stat(self):
        t=self.cur()
        if t[0]=='do':
            self.advance()
            b=self.parse_block()
            self.expect('end')
            return {'type':'do','block':b}
        elif t[0]=='while':
            self.advance()
            cond=self.parse_exp()
            self.expect('do')
            b=self.parse_block()
            self.expect('end')
            return {'type':'while','cond':cond,'block':b}
        elif t[0]=='repeat':
            self.advance()
            b=self.parse_block()
            self.expect('until')
            cond=self.parse_exp()
            return {'type':'repeat','block':b,'cond':cond}
        elif t[0]=='if':
            return self.parse_if()
        elif t[0]=='for':
            return self.parse_for()
        elif t[0]=='function':
            return self.parse_func_stat()
        elif t[0]=='local':
            return self.parse_local()
        else:
            saved=self.pos
            try:
