            self.expect('end')
            return {'type':'forin','names':names,'exps':exps,'block':b}
    def parse_func_stat(self):
        self.expect('function')
        fname=self.parse_funcname()
        body=self.parse_funcbody()
        return {'type':'funcdef','name':fname,'body':body}
    def parse_funcname(self):
        base=self.expect('NAME')[1]
        fields=[]
        method=None
        while self.cur()[0]=='.':
            self.advance()
            fields.append(self.expect('NAME')[1])
        if self.cur()[0]==':':
            self.advance()
            method=self.expect('NAME')[1]
        return {'base':base,'fields':fields,'method':method}
    def parse_funcbody(self):
        self.expect('(')
        params=[]
        vararg=False
        if self.cur()[0]!=')':
            if self.cur()[0]=='...':
                self.advance()
                vararg=True
            else:
                params.append(self.expect('NAME')[1])
                while self.cur()[0]==',':
                    self.advance()
                    if self.cur()[0]=='...':
                        self.advance()
                        vararg=True
                        break
                    params.append(self.expect('NAME')[1])
        self.expect(')')
        block=self.parse_block()
        self.expect('end')
        return {'params':params,'vararg':vararg,'block':block}
    def parse_local(self):
        self.expect('local')
        if self.cur()[0]=='function':
            self.advance()
            name=self.expect('NAME')[1]
            body=self.parse_funcbody()
            return {'type':'local_func','name':name,'body':body}
        else:
            names=[self.expect('NAME')[1]]
            while self.cur()[0]==',':
                self.advance()
                names.append(self.expect('NAME')[1])
            exps=[]
            if self.cur()[0]=='=':
                self.advance()
                exps=self.parse_explist()
