    def parse_var(self):
        t=self.cur()
        if t[0]!='NAME':
            raise LuaError(f"expected NAME near '{t[1]}'")
        self.advance()
        node={'type':'var','name':t[1]}
        while True:
            if self.cur()[0]=='.':
                self.advance()
                n=self.expect('NAME')[1]
                node={'type':'index','table':node,'key':n,'key_is_name':True}
            elif self.cur()[0]=='[':
                self.advance()
                k=self.parse_exp()
                self.expect(']')
                node={'type':'index','table':node,'key':k}
            else:
                break
        return node
    def parse_explist(self):
        exps=[self.parse_exp()]
        while self.cur()[0]==',':
            self.advance()
            exps.append(self.parse_exp())
        return exps
    BINOPS={'or':(1,'left'),'and':(2,'left'),'<':(3,'left'),'>':(3,'left'),'<=':(3,'left'),'>=':(3,'left'),'~=':(3,'left'),'==':(3,'left'),'..':(4,'right'),'+':(5,'left'),'-':(5,'left'),'*':(6,'left'),'/':(6,'left'),'%':(6,'left'),'//':(6,'left'),'^':(8,'right')}
    def parse_exp(self):
        return self.parse_sub(0)
    def parse_sub(self, minp):
        t=self.cur()
        if t[0] in ('not','#','-','~'):
            op=t[0]
            self.advance()
            e=self.parse_sub(7)
            node={'type':'unop','op':op,'exp':e}
        else:
            node=self.parse_simple()
        while True:
            op=self.cur()[0]
            if op not in self.BINOPS:
                break
            prec,assoc=self.BINOPS[op]
            if prec<minp:
                break
            self.advance()
            nxt=prec+1 if assoc=='left' else prec
            right=self.parse_sub(nxt)
            node={'type':'binop','op':op,'left':node,'right':right}
        return node
    def parse_simple(self):
        t=self.cur()
        if t[0]=='nil':
            self.advance()
            return {'type':'nil'}
        if t[0]=='false':
            self.advance()
            return {'type':'false'}
        if t[0]=='true':
            self.advance()
            return {'type':'true'}
        if t[0]=='NUMBER':
            self.advance()
            return {'type':'number','value':t[1]}
        if t[0]=='STRING':
            self.advance()
            return {'type':'string','value':t[1]}
        if t[0]=='...':
            self.advance()
            return {'type':'vararg'}
        if t[0]=='function':
            self.advance()
            body=self.parse_funcbody()
            return {'type':'func','body':body}
        if t[0]=='{':
            return self.parse_table()
        if t[0]=='(':
            self.advance()
            e=self.parse_exp()
            self.expect(')')
            return {'type':'paren','exp':e}
        return self.parse_prefix()
    def parse_prefix(self):
        t=self.cur()
        if t[0]=='NAME':
            self.advance()
            node={'type':'var','name':t[1]}
        elif t[0]=='(':
            self.advance()
            e=self.parse_exp()
            self.expect(')')
            node={'type':'paren','exp':e}
        else:
            raise LuaError(f"unexpected symbol near '{t[1]}'")
        while True:
            if self.cur()[0]=='.':
                self.advance()
                n=self.expect('NAME')[1]
                node={'type':'index','table':node,'key':n,'key_is_name':True}
            elif self.cur()[0]=='[':
                self.advance()
                k=self.parse_exp()
                self.expect(']')
                node={'type':'index','table':node,'key':k}
            elif self.cur()[0]==':':
                self.advance()
                m=self.expect('NAME')[1]
                args=self.parse_args()
                node={'type':'method_call','obj':node,'method':m,'args':args}
            elif self.cur()[0] in ('(','{','STRING'):
                args=self.parse_args()
                node={'type':'call','func':node,'args':args}
            else:
                break
        return node
    def parse_args(self):
        t=self.cur()
        if t[0]=='(':
            self.advance()
            exps=[]
            if self.cur()[0]!=')':
                exps=self.parse_explist()
            self.expect(')')
            return exps
        elif t[0]=='{':
            tbl=self.parse_table()
            return [tbl]
        elif t[0]=='STRING':
            self.advance()
            return [{'type':'string','value':t[1]}]
        else:
            raise LuaError(f"unexpected symbol near '{t[1]}'")
    def parse_table(self):
        self.expect('{')
        fields=[]
        while self.cur()[0]!='}':
            if self.cur()[0]=='EOF':
                raise LuaError("unexpected <eof> near '}'")
            # field
            if self.cur()[0]=='[':
                self.advance()
                k=self.parse_exp()
                self.expect(']')
                self.expect('=')
                v=self.parse_exp()
                fields.append({'key':k,'val':v})
            elif self.cur()[0]=='NAME' and self.peek(1)[0]=='=':
                kn=self.cur()[1]
                self.advance()
                self.advance()
                v=self.parse_exp()
                fields.append({'key':kn,'val':v,'is_name':True})
            else:
                v=self.parse_exp()
                fields.append({'key':None,'val':v})
            if self.cur()[0] in (',',';'):
                self.advance()
        self.expect('}')
        return {'type':'table','fields':fields}

