    def call(self, func, args):
        if func is nil:
            raise LuaError("attempt to call a nil value")
        if isinstance(func, LuaBuiltin):
            try:
                r=func.fn(*args)
                return r
            except LuaError:
                raise
            except SystemExit:
                raise
            except Exception as e:
                raise LuaError(str(e))
        if isinstance(func, LuaFunction):
            body=func.body
            params=body['params']
            vararg=body['vararg']
            new_env=Env(outer=func.closure_env if isinstance(func.closure_env, Env) else self.globals)
            for i,pn in enumerate(params):
                if i < len(args):
                    new_env.set_local(pn, args[i])
                else:
                    new_env.set_local(pn, nil)
            if vararg:
                extra=args[len(params):]
                self.vararg_stack.append(extra)
            self.push(new_env)
            try:
                self.exec_block(body['block'])
                return nil
            except ReturnExc as re:
                vals=re.vals
                if not vals:
                    return nil
                if len(vals)==1:
                    return vals[0]
                return tuple(vals)
            finally:
                if vararg:
                    self.vararg_stack.pop()
                self.pop()
        raise LuaError(f"attempt to call a {lua_type(func)} value")
    def load_chunk(self, code, filename):
        if code.startswith('#!'):
            idx=code.find('\\n')
            if idx!=-1:
                code=code[idx+1:]
        lex=Lexer(code)
        toks=lex.tokenize()
        parser=Parser(toks)
        try:
            ast=parser.parse_chunk()
        except LuaError as e:
            # format as Lua error with file:line
            # e.msg already contains line info
            raise LuaError(f"{filename}: {e.msg}")
        return ast
    def exec_chunk(self, ast, env=None):
        if env is None:
            env=self.globals
        # push new env? Actually chunk runs in globals env
        # For simplicity, use current env stack top as globals? We'll push new env with outer = env
        self.push(Env(outer=env if isinstance(env, Env) else None))
        try:
            self.exec_block(ast['block'])
            return nil
        except ReturnExc as re:
            vals=re.vals
            if not vals:
                return nil
            if len(vals)==1:
                return vals[0]
            return tuple(vals)
        finally:
            self.pop()
    def exec_block(self, block):
        for stat in block['stats']:
            self.exec_stat(stat)
    def exec_stat(self, stat):
        t=stat['type']
        if t=='break':
            raise BreakExc()
        elif t=='do':
            self.push(Env(outer=self.cur_env()))
            try:
                self.exec_block(stat['block'])
            finally:
                self.pop()
        elif t=='while':
            while is_truthy(self.eval_exp(stat['cond'])):
                try:
                    self.push(Env(outer=self.cur_env()))
                    self.exec_block(stat['block'])
                    self.pop()
                except BreakExc:
                    self.pop()
                    break
        elif t=='repeat':
            self.push(Env(outer=self.cur_env()))
            try:
                while True:
                    self.exec_block(stat['block'])
                    if is_truthy(self.eval_exp(stat['cond'])):
                        break
            except BreakExc:
                pass
            finally:
                self.pop()
        elif t=='if':
            if is_truthy(self.eval_exp(stat['cond'])):
                self.push(Env(outer=self.cur_env()))
                try:
                    self.exec_block(stat['then'])
                finally:
                    self.pop()
            else:
                done=False
                for ec, eb in stat['elseif']:
                    if is_truthy(self.eval_exp(ec)):
                        self.push(Env(outer=self.cur_env()))
                        try:
                            self.exec_block(eb)
                        finally:
                            self.pop()
                        done=True
                        break
                if not done and stat['else'] is not None:
                    self.push(Env(outer=self.cur_env()))
                    try:
                        self.exec_block(stat['else'])
                    finally:
                        self.pop()
        elif t=='fornum':
            s=self.eval_exp(stat['start'])
            e=self.eval_exp(stat['end'])
            step=self.eval_exp(stat['step']) if stat['step'] else 1.0
            try:
                sv=float(s) if isinstance(s,(int,float)) else float(s)
                ev=float(e) if isinstance(e,(int,float)) else float(e)
                stv=float(step) if isinstance(step,(int,float)) else float(step)
            except:
                raise LuaError("'for' initial value must be a number")
            name=stat['name']
            self.push(Env(outer=self.cur_env()))
            self.cur_env().set_local(name, sv)
            try:
                cv=sv
                while (stv>0 and cv<=ev) or (stv<0 and cv>=ev):
                    self.cur_env().set_local(name, cv)
                    try:
                        self.exec_block(stat['block'])
                    except BreakExc:
                        break
                    cv+=stv
            finally:
                self.pop()
        elif t=='forin':
            explist=[]
            for ex in stat['exps']:
                v=self.eval_exp(ex)
                if isinstance(v,tuple):
                    explist.extend(v)
                else:
                    explist.append(v)
            f=explist[0] if len(explist)>0 else nil
            s=explist[1] if len(explist)>1 else nil
            var=explist[2] if len(explist)>2 else nil
            self.push(Env(outer=self.cur_env()))
            control=var
            while True:
                r=self.call(f, [s, control])
                if isinstance(r,tuple):
                    if not r or r[0] is nil:
                        break
                    nxt=r[0]
                    vals=r[1:]
                else:
                    if r is nil:
                        break
                    nxt=r
                    vals=[]
                names=stat['names']
                self.cur_env().set_local(names[0], nxt)
                for i,n in enumerate(names[1:]):
                    if i < len(vals):
                        self.cur_env().set_local(n, vals[i])
                    else:
                        self.cur_env().set_local(n, nil)
                control=nxt
                try:
                    self.exec_block(stat['block'])
                except BreakExc:
                    break
            self.pop()
        elif t=='funcdef':
            fname=stat['name']
            body=stat['body']
            # closure
            # For method, add self param
            if fname['method']:
                if 'self' not in body['params']:
                    body['params'] = ['self'] + body['params']
            closure=LuaFunction(body, self.cur_env())
            base_name=fname['base']
            tbl=self.cur_env().get(base_name)
            if tbl is nil:
                if not fname['fields'] and fname['method'] is None:
                    self.cur_env().set(base_name, closure)
                else:
                    tbl=LuaTable()
                    self.cur_env().set(base_name, tbl)
                    cur=tbl
                    for fld in fname['fields'][:-1]:
                        nxt=cur.rawget(fld) if isinstance(cur, LuaTable) else nil
                        if nxt is nil:
                            nxt=LuaTable()
                            cur.rawset(fld, nxt)
                        cur=nxt
                    if fname['fields']:
                        last=fname['fields'][-1]
                        if fname['method'] is None:
                            cur.rawset(last, closure)
                        else:
                            mtbl=cur.rawget(last) if isinstance(cur, LuaTable) else nil
                            if mtbl is nil:
                                mtbl=LuaTable()
                                cur.rawset(last, mtbl)
                            mtbl.rawset(fname['method'], closure)
                    else:
                        if fname['method']:
                            cur.rawset(fname['method'], closure)
            else:
                if not fname['fields'] and fname['method'] is None:
                    self.cur_env().set(base_name, closure)
                else:
                    cur=tbl
                    for fld in fname['fields'][:-1]:
                        nxt=cur.rawget(fld) if isinstance(cur, LuaTable) else nil
                        if nxt is nil:
                            nxt=LuaTable()
                            cur.rawset(fld, nxt)
                        cur=nxt
                    if fname['fields']:
                        last=fname['fields'][-1]
                        if fname['method'] is None:
                            cur.rawset(last, closure)
                        else:
                            mtbl=cur.rawget(last) if isinstance(cur, LuaTable) else nil
                            if mtbl is nil:
                                mtbl=LuaTable()
                                cur.rawset(last, mtbl)
                            mtbl.rawset(fname['method'], closure)
                    else:
                        if fname['method']:
                            cur.rawset(fname['method'], closure)
        elif t=='local_func':
            closure=LuaFunction(stat['body'], self.cur_env())
            self.cur_env().set_local(stat['name'], closure)
        elif t=='local_assign':
            names=stat['names']
            exps=stat['exps']
            vals=[]
            for ex in exps:
                v=self.eval_exp(ex)
                if isinstance(v,tuple):
                    if ex==exps[-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if v else nil)
                else:
                    vals.append(v)
            for i,n in enumerate(names):
                if i < len(vals):
                    self.cur_env().set_local(n, vals[i])
                else:
                    self.cur_env().set_local(n, nil)
        elif t=='assign':
            vars=stat['vars']
            exps=stat['exps']
            vals=[]
            for ex in exps:
                v=self.eval_exp(ex)
                if isinstance(v,tuple):
                    if ex==exps[-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if v else nil)
                else:
                    vals.append(v)
            for i,var in enumerate(vars):
                val=vals[i] if i < len(vals) else nil
                self.assign_var(var, val)
        elif t=='call_stat':
            self.eval_exp(stat['call'])
        elif t=='return':
            vals=[]
            for ex in stat['exps']:
                v=self.eval_exp(ex)
                if isinstance(v,tuple):
                    if ex==stat['exps'][-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if v else nil)
                else:
                    vals.append(v)
            raise ReturnExc(vals)
        else:
            raise LuaError(f"unhandled stat {t}")
    def assign_var(self, var, val):
        if var['type']=='var':
            self.cur_env().set(var['name'], val)
        elif var['type']=='index':
            tbl=self.eval_exp(var['table'])
            if var.get('key_is_name'):
                k=var['key']
            else:
                k=self.eval_exp(var['key']) if isinstance(var['key'], dict) else var['key']
                if isinstance(k, dict):
                    # if key is string literal node handled earlier
                    k=k.get('value', k)
            if not isinstance(tbl, LuaTable):
                raise LuaError(f"attempt to index a {lua_type(tbl)} value")
            r=tbl.set(k, val)
            if isinstance(r, LuaMetaCall):
                self.call(r.func, list(r.args))
        else:
            raise LuaError("invalid assign")
    def eval_exp(self, node):
        t=node['type']
        if t=='nil':
            return nil
        if t=='false':
            return False
        if t=='true':
            return True
        if t=='number':
            return node['value']
        if t=='string':
            return node['value']
        if t=='vararg':
            if self.vararg_stack:
                return tuple(self.vararg_stack[-1])
            return nil
        if t=='var':
            return self.cur_env().get(node['name'])
        if t=='index':
            tbl=self.eval_exp(node['table'])
            if node.get('key_is_name'):
                k=node['key']
            else:
                kk=node['key']
                if isinstance(kk, dict):
                    if kk['type']=='string':
                        k=kk['value']
                    else:
                        k=self.eval_exp(kk)
                elif isinstance(kk, str):
                    k=kk
                else:
                    k=self.eval_exp(kk)
            if isinstance(tbl, LuaTable):
                v=tbl.get(k)
                if isinstance(v, LuaMetaCall):
                    r=self.call(v.func, list(v.args))
                    if isinstance(r,tuple):
                        return r[0] if r else nil
                    return r
                return v
            if isinstance(tbl, str):
                # string method lookup
                slib=self.globals.get('string')
                if isinstance(slib, LuaTable):
                    m=slib.rawget(k)
                    if m is not nil:
                        return m
                return nil
            raise LuaError(f"attempt to index a {lua_type(tbl)} value")
        if t=='call':
            func=self.eval_exp(node['func'])
            args=[]
            for a in node['args']:
                v=self.eval_exp(a)
                if isinstance(v,tuple):
                    if a==node['args'][-1]:
                        args.extend(v)
                    else:
                        args.append(v[0] if v else nil)
                else:
                    args.append(v)
            return self.call(func, args)
        if t=='method_call':
            obj=self.eval_exp(node['obj'])
            meth_name=node['method']
            if isinstance(obj, LuaTable):
                meth=obj.get(meth_name)
                if isinstance(meth, LuaMetaCall):
                    meth=self.call(meth.func, list(meth.args))
            elif isinstance(obj, str):
                slib=self.globals.get('string')
                meth=slib.rawget(meth_name) if isinstance(slib, LuaTable) else nil
            else:
                meth=nil
            args=[obj]
            for a in node['args']:
                v=self.eval_exp(a)
                if isinstance(v,tuple):
                    if a==node['args'][-1]:
                        args.extend(v)
                    else:
                        args.append(v[0] if v else nil)
                else:
                    args.append(v)
            return self.call(meth, args)
        if t=='paren':
            return self.eval_exp(node['exp'])
        if t=='func':
            return LuaFunction(node['body'], self.cur_env())
        if t=='table':
            tbl=LuaTable()
            idx=1
            for fld in node['fields']:
                if fld['key'] is None:
                    v=self.eval_exp(fld['val'])
                    if isinstance(v,tuple):
                        for vv in v:
                            tbl.rawset(idx, vv)
                            idx+=1
                    else:
                        tbl.rawset(idx, v)
                        idx+=1
                else:
                    if fld.get('is_name'):
                        k=fld['key']
                    else:
                        k=self.eval_exp(fld['key'])
                    v=self.eval_exp(fld['val'])
                    tbl.rawset(k, v)
            return tbl
        if t=='binop':
            l=self.eval_exp(node['left'])
            r=self.eval_exp(node['right'])
            op=node['op']
            return self.eval_binop(op,l,r)
        if t=='unop':
            e=self.eval_exp(node['exp'])
            return self.eval_unop(node['op'], e)
        raise LuaError(f"unhandled exp {t}")
    def eval_binop(self, op,l,r):
        def to_num(v):
            if isinstance(v,(int,float)):
                return float(v)
            if isinstance(v,str):
                try:
                    return float(v.strip())
                except:
                    return None
            return None
        if op in ('+','-','*','/','%','^','//'):
            ln=to_num(l); rn=to_num(r)
            if ln is None or rn is None:
                raise LuaError(f"attempt to perform arithmetic on a {lua_type(l)} value")
            if op=='+':
                return ln+rn
            if op=='-':
                return ln-rn
            if op=='*':
                return ln*rn
            if op=='/':
                return ln/rn if rn!=0 else float('inf')
            if op=='%':
                return ln%rn
            if op=='^':
                return ln**rn
            if op=='//':
                return math.floor(ln/rn)
        if op=='..':
            def to_s(v):
                if isinstance(v,str):
                    return v
                if isinstance(v,(int,float)):
                    if isinstance(v,float) and v.is_integer():
                        return str(int(v))
                    return ('%.14g'%v)
                raise LuaError(f"attempt to concatenate a {lua_type(v)} value")
            return to_s(l)+to_s(r)
        if op in ('==','~='):
            eq = (l is r) or (l==r) or (isinstance(l,float) and isinstance(r,float) and l==r)
            # need proper equality for tables etc by identity
            if isinstance(l, LuaTable) or isinstance(r, LuaTable):
                eq = l is r
            if isinstance(l,bool) or isinstance(r,bool):
                # careful: True vs 1? In Lua, true not equal 1
                if type(l)!=type(r):
                    # if one is bool and other not bool, not equal
                    if isinstance(l,bool) or isinstance(r,bool):
                        eq=False
            if op=='==':
                return eq
            else:
                return not eq
        if op in ('<','>','<=','>='):
            if isinstance(l,(int,float)) and isinstance(r,(int,float)):
                lv=float(l); rv=float(r)
                if op=='<': return lv<rv
                if op=='>': return lv>rv
                if op=='<=': return lv<=rv
                if op=='>=': return lv>=rv
            if isinstance(l,str) and isinstance(r,str):
                if op=='<': return l<r
                if op=='>': return l>r
                if op=='<=': return l<=r
                if op=='>=': return l>=r
            raise LuaError(f"attempt to compare {lua_type(l)} with {lua_type(r)}")
        if op=='and':
            return l if is_falsy(l) else r
        if op=='or':
            return l if is_truthy(l) else r
        raise LuaError(f"unsupported op {op}")
    def eval_unop(self, op,e):
        if op=='-':
            if isinstance(e,(int,float)):
                return -float(e)
            if isinstance(e,str):
                try:
                    return -float(e.strip())
                except:
                    pass
            raise LuaError(f"attempt to perform arithmetic on a {lua_type(e)} value")
        if op=='not':
            return is_falsy(e)
        if op=='#':
            if isinstance(e,str):
                return float(len(e))
            if isinstance(e, LuaTable):
                length=0
                for i,v in enumerate(e.array):
                    if v is nil:
                        break
                    length=i+1
                return float(length)
            raise LuaError(f"attempt to get length of a {lua_type(e)} value")
        raise LuaError(f"unsupported unop {op}")

# End interpreter classes

def main():
    argv=sys.argv
    prog=argv[0]
    # parse logic same as earlier
    jit_enabled=True
    jit_flags=set(['fold','cse','dce','fwd','dse','narrow','loop','abc','sink','fuse'])
    jit_params={'maxtrace':1000,'maxrecord':4000,'maxirconst':500,'maxside':100,'maxsnap':500,'hotloop':56,'hotexit':10,'tryside':4,'instunroll':4,'loopunroll':15,'callunroll':3,'recunroll':2,'sizemcode':64,'maxmcode':2048}
    flag_order=['fold','cse','dce','fwd','dse','narrow','loop','abc','sink','fuse','fma']
    valid_flags=set(flag_order)
    valid_params=set(jit_params.keys())
    def set_level(lvl):
        jit_flags.clear()
        if lvl>=1:
            jit_flags.update(['fold','cse','dce'])
        if lvl>=2:
            jit_flags.update(['narrow','loop'])
        if lvl>=3:
            jit_flags.update(['fwd','dse','abc','sink','fuse'])
    def try_flag(s):
        if not s:
            return None
        sign=None
        core=s
        if s[0]=='+':
            sign='+'
            core=s[1:]
        elif s[0]=='-':
            sign='-'
            core=s[1:]
        if core in valid_flags:
            if sign in (None,'+'):
                jit_flags.add(core)
            else:
                jit_flags.discard(core)
            return True
        return None
    def print_usage():
        sys.stderr.write(USAGE.format(prog=prog))
    def parse_argv(argv):
        options_before=[]
        parsed=[]
        i=1
        script=None
        script_args=[]
        stop=False
        while i < len(argv):
            a=argv[i]
            if stop:
                if script is None:
                    script=a
                else:
                    script_args.append(a)
                i+=1
                continue
            if a=='--':
                options_before.append(a)
                parsed.append(('dashdash',))
                stop=True
                i+=1
                continue
            if a=='-':
                options_before.append(a)
                script='-'
                i+=1
                while i < len(argv):
                    script_args.append(argv[i])
                    i+=1
                break
            if not a.startswith('-'):
                script=a
                i+=1
                while i < len(argv):
                    script_args.append(argv[i])
                    i+=1
                break
            if a.startswith('-O'):
                options_before.append(a)
                parsed.append(('O', a[2:]))
                i+=1
                continue
            if a.startswith('-j'):
                if len(a)>2:
                    cmd=a[2:]
                    options_before.append(a)
                    parsed.append(('j', cmd))
                else:
                    if i+1 >= len(argv):
                        return None,None,None,None,'usage'
                    cmd=argv[i+1]
                    options_before.append(a)
                    options_before.append(cmd)
                    parsed.append(('j', cmd))
                    i+=1
                i+=1
                continue
            if a.startswith('-e'):
                if len(a)>2:
                    chunk=a[2:]
                    options_before.append(a)
                    parsed.append(('e', chunk))
                else:
                    if i+1 >= len(argv):
                        return None,None,None,None,'usage'
                    chunk=argv[i+1]
                    options_before.append(a)
                    options_before.append(chunk)
                    parsed.append(('e', chunk))
                    i+=1
                i+=1
                continue
            if a.startswith('-l'):
                if len(a)>2:
                    lib=a[2:]
                    options_before.append(a)
                    parsed.append(('l', lib))
                else:
                    if i+1 >= len(argv):
                        return None,None,None,None,'usage'
                    lib=argv[i+1]
                    options_before.append(a)
                    options_before.append(lib)
                    parsed.append(('l', lib))
                    i+=1
                i+=1
                continue
            if a.startswith('-b'):
                options_before.append(a)
                return None,None,options_before,parsed,'b_error'
            if a=='-i':
                options_before.append(a)
                parsed.append(('i',))
                i+=1
                continue
            if a=='-v':
                options_before.append(a)
                parsed.append(('v',))
                i+=1
                continue
            if a=='-E':
                options_before.append(a)
                parsed.append(('E',))
                i+=1
                continue
            return None,None,options_before,parsed,'usage'
        return script, script_args, options_before, parsed, None

    script, script_args, options_before, parsed, err = parse_argv(argv)
    if err=='usage':
        print_usage()
        sys.exit(1)
    if err=='b_error':
        sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\\n")
        sys.exit(1)

    ignore_env = any(p[0]=='E' for p in (parsed or []))
    has_v = any(p[0]=='v' for p in (parsed or []))
    has_i = any(p[0]=='i' for p in (parsed or []))

    for opt in (parsed or []):
        if opt[0]=='O':
            ostr=opt[1]
            if ostr=='':
                set_level(3)
                continue
            parts=ostr.split(',')
            for part in parts:
                if part=='':
                    sys.stderr.write(f"{prog}: bad argument #1 to '?' (string expected, got nil)\\n")
                    sys.exit(1)
                if part.isdigit() and len(part)==1:
                    set_level(int(part))
                    continue
                if try_flag(part):
                    continue
                if '=' in part:
                    pn,pv = part.split('=',1)
                    if pn in valid_params:
                        if pv=='':
                            continue
                        if pv.startswith('-'):
                            sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{part}'\\n")
                            sys.exit(1)
                        try:
                            iv=int(pv)
                            if iv<0:
                                raise ValueError
                            jit_params[pn]=iv
                            continue
                        except:
                            sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{part}'\\n")
                            sys.exit(1)
                    else:
                        sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{part}'\\n")
                        sys.exit(1)
                sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{part}'\\n")
                sys.exit(1)

    for opt in (parsed or []):
        if opt[0]=='j':
            cmd=opt[1]
            if '=' in cmd:
                base=cmd.split('=',1)[0]
                if base in ('on','off','flush'):
                    sys.stderr.write(f"{prog}: bad argument #1 to '?' (function expected, got string)\\n")
                    sys.exit(1)
                else:
                    sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\\n")
                    sys.exit(1)
            else:
                base=cmd
                if base in ('on','off','flush'):
                    if base=='on':
                        jit_enabled=True
                    elif base=='off':
                        jit_enabled=False
                else:
                    sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\\n")
                    sys.exit(1)

    if has_v:
        sys.stdout.write(VERSION_STR+"\\n")

    def find_script_idx(argv):
        i=1
        stop=False
        while i < len(argv):
            a=argv[i]
            if stop:
                return i
            if a=='--':
                stop=True
                i+=1
                continue
            if a=='-':
                return i
            if not a.startswith('-'):
                return i
            if a.startswith('-O'):
                i+=1
                continue
            if a.startswith('-j'):
                if len(a)>2:
                    i+=1
                else:
                    i+=2
                continue
            if a.startswith('-e'):
                if len(a)>2:
                    i+=1
                else:
                    i+=2
                continue
            if a.startswith('-l'):
                if len(a)>2:
                    i+=1
                else:
                    i+=2
                continue
            if a.startswith('-b'):
                i+=1
                continue
            if a in ('-i','-v','-E'):
                i+=1
                continue
            return None
        return None

    script_idx = find_script_idx(argv)

    # Build arg table for Lua
    # For interpreter's globals, we will set arg as LuaTable

    # Now create interpreter and set up package.path etc.

    interp = Interpreter()
    interp.jit_enabled = jit_enabled
    interp.jit_flags = jit_flags
    interp.jit_params = jit_params

    # handle env
    if not ignore_env:
        # LUA_PATH
        lp = os.getenv('LUA_PATH')
        if lp is not None:
            # According to tests: LUA_PATH=";;" should result in " ;./?.lua;...;"? Actually observed earlier: LUA_PATH=";;" gave " ;./?.lua;...;" (semicolon at start?). Let's emulate standard Lua behavior: ;; replaced with default path?
            # In Lua, ;; in LUA_PATH is replaced with default path.
            # We saw: LUA_PATH=";;" gave ";./?.lua;..." -> leading ; means empty? Actually output ";./?.lua;..." includes leading ; then default path.
            # Let's implement: if lp contains ";;", replace ";;" with ";"+default_path+";"
            # And if lp == ""? Earlier we saw empty LUA_PATH gave empty path (just newline). So if lp=="" then path becomes ""? That matches observation: LUA_PATH="" gave empty string (just newline, no default)
            # For ";;", replacement yields ";" + default + ";" -> which matches observed leading ; then default then ;
            # We'll implement simple replacement
            default_path = "./?.lua;/usr/local/share/luajit-2.1/?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua"
            if ";;" in lp:
                lp = lp.replace(";;", ";"+default_path+";")
            else:
